export const emptyExpression = {
  name: "新的表情",
  pixels: "0".repeat(418),
  color: "#e47bb7",
};

export function encodeExpression(value) {
  return Buffer.from(JSON.stringify(value)).toString("base64url");
}

export function decodeExpression(data) {
  if (typeof data !== "string" || data.length > 16384)
    throw new Error("invalid data");
  const value = JSON.parse(Buffer.from(data, "base64url").toString("utf8"));
  if (typeof value.pixels !== "string" || !/^[01]{418}$/.test(value.pixels))
    throw new Error("invalid expression");
  return {
    name: String(value.name || "未命名").slice(0, 40),
    pixels: value.pixels,
    color: String(value.color ?? "#e47bb7"),
  };
}
